#!/usr/bin/env python3
from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')


def rep(old,new):
    global s
    if old not in s:
        raise SystemExit('Trecho não encontrado: '+old[:180])
    s=s.replace(old,new,1)

rep('PILOTO v0.12 web','PILOTO v0.13 web')
rep(" const [parts,atual,historico,amostra,gastos]=await Promise.all([\n  Promise.all(files.map(f=>fetch(f,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Base não encontrada: '+f);return r.text()}))),\n  getJSON('dados/votacoes_senado.json'),getJSON('dados/votacoes_senado_historico.json'),getJSON('dados/validacao_amostra_votacoes_2019_2025.json',false),getJSON('dados/gastos_mandato_senado.json')\n ]);",
" const [parts,atual,historico,amostra,gastos,emendas]=await Promise.all([\n  Promise.all(files.map(f=>fetch(f,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Base não encontrada: '+f);return r.text()}))),\n  getJSON('dados/votacoes_senado.json'),getJSON('dados/votacoes_senado_historico.json'),getJSON('dados/validacao_amostra_votacoes_2019_2025.json',false),getJSON('dados/gastos_mandato_senado.json'),getJSON('dados/emendas_parlamentares.json')\n ]);")
rep(" if(gastos.escopo!=='gastos_mandato_senado'||!Array.isArray(gastos.por_ano)||gastos.por_ano.length<8)throw Error('Base de gastos do mandato em formato inesperado');",
" if(gastos.escopo!=='gastos_mandato_senado'||!Array.isArray(gastos.por_ano)||gastos.por_ano.length<8)throw Error('Base de gastos do mandato em formato inesperado');\n if(emendas.escopo!=='emendas_parlamentares_autor'||!Array.isArray(emendas.registros)||!emendas.registros.length)throw Error('Base oficial de emendas em formato inesperado');")
rep(" D.gastos_mandato_oficial=gastos;\n return D;"," D.gastos_mandato_oficial=gastos;\n D.emendas_oficial=emendas;\n return D;")
rep(" const p=D.politico,V=D.votacoes_nominais||[],E=D.emendas_carregadas||[],R=D.registros||[],F=D.fin||[],G=D.gastos_mandato||[],GO=D.gastos_mandato_oficial||null,VM=D.votacoes_meta||{};\n const campanha=F.find(x=>x.tipo==='despesa_campanha'&&x.categoria==='Total declarado')?.valor||0,receita=F.find(x=>x.tipo==='receita_campanha'&&x.categoria==='Total arrecadado')?.valor||0,er=D.emendas_resumo||{};",
" const p=D.politico,V=D.votacoes_nominais||[],EO=D.emendas_oficial||null,E=EO?.registros||D.emendas_carregadas||[],R=D.registros||[],F=D.fin||[],G=D.gastos_mandato||[],GO=D.gastos_mandato_oficial||null,VM=D.votacoes_meta||{};\n const campanha=F.find(x=>x.tipo==='despesa_campanha'&&x.categoria==='Total declarado')?.valor||0,receita=F.find(x=>x.tipo==='receita_campanha'&&x.categoria==='Total arrecadado')?.valor||0,er=EO?{empenhado:EO.totais.empenhado,pago:EO.totais.pago,por_area:EO.por_area}:D.emendas_resumo||{};")
rep("<b>${E.length}</b><span>emendas carregadas</span>","<b>${EO?.quantidade_emendas_distintas||E.length}</b><span>emendas distintas do autor</span>")

start=s.index(" const areas=Object.entries(er.por_area||{});")
end=s.index(" const cats=F.filter",start)
block=r''' const areas=Object.entries(er.por_area||{});
 if(GO&&Array.isArray(GO.por_ano)){
  const emendaYears=(EO?.anos||[...new Set(E.map(e=>e.ano).filter(Boolean))]).slice().sort((a,b)=>b-a);
  document.getElementById('dinheiro').innerHTML=`<h2>Dinheiro público</h2><div class="notice"><b>Dois fluxos separados.</b> Gastos do mandato no Senado e emendas parlamentares aparecem em painéis diferentes. A base de emendas agora é carregada diretamente dos dados abertos oficiais da CGU/Portal da Transparência para o autor identificado.</div><div class="money-subtabs"><button type="button" class="active" data-money="mandato">Gastos do mandato no Senado</button><button type="button" data-money="emendas">Emendas parlamentares</button></div><div id="money-mandato" class="money-subpanel active"><div class="notice oknote"><b>Gastos do mandato no Senado — 2019 a 2026.</b> Valores coletados diretamente da API oficial do Senado e atualizados automaticamente. O ano de 2026 é parcial. A soma reúne CEAPS e os gastos não inclusos na CEAPS exibidos pelo Senado; não representa o custo integral do mandato.</div><div class="money-summary"><div class="record"><span class="source">CEAPS no período</span><b>${money(GO.total_ceaps_periodo)}</b></div><div class="record"><span class="source">Fora da CEAPS exibidos</span><b>${money(GO.total_fora_ceaps_periodo)}</b></div><div class="record"><span class="source">Soma das duas seções</span><b>${money(GO.total_mostrado_periodo)}</b></div></div><div class="source">Atualizado em ${esc(fmtDateTime(GO.atualizado_em_utc))}. *2026 parcial e sujeito a novos lançamentos, ajustes ou estornos.</div><h3>Evolução anual dos recursos exibidos</h3>${expenseTrendHtml(GO.por_ano)}<h3>Composição por categoria</h3><div class="money-controls"><select id="expenseYear"><option value="periodo">Período 2019–2026</option>${GO.por_ano.slice().reverse().map(x=>`<option value="${x.ano}">${x.ano}${x.parcial?' (parcial)':''}</option>`).join('')}</select><select id="expenseGroup"><option value="ceaps">CEAPS</option><option value="fora">Gastos fora da CEAPS exibidos</option></select></div><div id="expenseChart"></div><div id="expenseTable"></div><div id="expenseSource" class="source-actions"></div></div><div id="money-emendas" class="money-subpanel"><div class="notice oknote"><b>Emendas parlamentares — base oficial da CGU.</b> O portal carrega os registros do arquivo aberto de Emendas Parlamentares filtrados pelo autor. Valores de 2026 são parciais e toda execução pode receber novos pagamentos, restos a pagar, cancelamentos ou ajustes.</div><div class="money-summary"><div class="record"><span class="source">Empenhado nos registros</span><b>${money(EO?.totais?.empenhado||0)}</b></div><div class="record"><span class="source">Pago no orçamento</span><b>${money(EO?.totais?.pago||0)}</b></div><div class="record"><span class="source">Pago em restos a pagar</span><b>${money(EO?.totais?.rap_pago||0)}</b></div><div class="record"><span class="source">Emendas distintas</span><b>${EO?.quantidade_emendas_distintas||0}</b></div><div class="record"><span class="source">Linhas de execução/localidade</span><b>${EO?.quantidade_registros||E.length}</b></div><div class="record"><span class="source">Anos disponíveis</span><b>${esc((EO?.anos||[]).join('–')||'—')}</b></div></div><div class="source">Atualizado em ${esc(fmtDateTime(EO?.atualizado_em_utc))}. Fonte: Portal da Transparência / CGU.</div><div class="emenda-controls"><select id="emendaYear"><option value="">Todos os anos disponíveis</option>${emendaYears.map(y=>`<option value="${y}">${y}${y===EO?.ano_corrente_parcial?' (parcial)':''}</option>`).join('')}</select><select id="emendaMetric"><option value="empenhado">Valor empenhado</option><option value="pago">Valor pago</option><option value="rap_pago">Restos a pagar pagos</option></select></div><div id="emendaSummary" class="source"></div><div class="emenda-charts"><div><h3>Por área apoiada</h3><div id="emendaAreaChart"></div></div><div><h3>Por região destinatária</h3><div id="emendaRegionChart"></div><div class="source">A região é a informada pelo próprio arquivo aberto da CGU. Registros sem regionalização permanecem como “Não informado”.</div></div></div><div class="source-actions"><a class="btn" href="${esc(EO?.fonte_download||'https://portaldatransparencia.gov.br/download-de-dados/emendas-parlamentares')}" target="_blank" rel="noopener">Dados abertos oficiais</a><a class="btn secondary" href="${esc(EO?.fonte_dicionario||'https://portaldatransparencia.gov.br/dicionario-de-dados/emendas-parlamentares')}" target="_blank" rel="noopener">Dicionário dos dados</a></div><h3>Registros de emendas</h3><div class="table-scroll"><table><thead><tr><th>Ano</th><th>Emenda</th><th>Área</th><th>Localidade</th><th>Região</th><th>Empenhado</th><th>Pago</th><th>RAP pago</th><th>Fonte</th></tr></thead><tbody id="emendaRows"></tbody></table></div></div>`;
  const renderExpense=()=>{const y=document.getElementById('expenseYear').value,g=document.getElementById('expenseGroup').value;let items,total,label,source='https://www12.senado.leg.br/dados-abertos/administrativo/senadores/cotas-para-exercicio-da-atividade-parlamentar';if(y==='periodo'){items=g==='ceaps'?GO.agregado_ceaps:GO.agregado_fora_ceaps;total=g==='ceaps'?GO.total_ceaps_periodo:GO.total_fora_ceaps_periodo;label=(g==='ceaps'?'CEAPS':'Fora da CEAPS')+' · 2019–2026'}else{const row=GO.por_ano.find(x=>String(x.ano)===y);items=g==='ceaps'?row.ceaps:row.fora_ceaps;total=g==='ceaps'?row.total_ceaps:row.total_fora_ceaps;label=(g==='ceaps'?'CEAPS':'Fora da CEAPS')+' · '+y+(row.parcial?' parcial':'');source=row.fonte_visual}document.getElementById('expenseChart').innerHTML=donutHtml(items,total,label);document.getElementById('expenseTable').innerHTML=expenseRowsTable(items,total);document.getElementById('expenseSource').innerHTML=`<a class="btn" href="${esc(source)}" target="_blank" rel="noopener">Abrir fonte oficial do Senado</a>`};
  const renderEmendas=()=>{const y=document.getElementById('emendaYear').value,field=document.getElementById('emendaMetric').value;const rows=E.filter(e=>!y||String(e.ano)===y);const total=rows.reduce((a,e)=>a+Number(e[field]||0),0);const byArea=aggregateEmendas(rows,e=>e.funcao,field);const byRegion=aggregateEmendas(rows,e=>e.regiao||'Não informado',field);document.getElementById('emendaSummary').textContent=`${rows.length} linha(s) de execução/localidade · ${new Set(rows.map(e=>e.codigo_emenda).filter(Boolean)).size} emenda(s) distinta(s) · ${field==='empenhado'?'Empenhado':field==='pago'?'Pago':'RAP pago'}: ${money(total)}`;document.getElementById('emendaAreaChart').innerHTML=barsHtml(byArea,total);document.getElementById('emendaRegionChart').innerHTML=donutHtml(byRegion,total,(y||'Todos os anos')+' · '+(field==='empenhado'?'empenhado':field==='pago'?'pago':'RAP pago'));document.getElementById('emendaRows').innerHTML=rows.slice(0,250).map(e=>`<tr><td>${esc(e.ano)}</td><td><b>${esc(e.codigo_emenda||'')}</b><br><span class="source">${esc(e.tipo_emenda||'')}</span></td><td><b>${esc(e.funcao)}</b><br><span class="source">${esc(e.subfuncao||'')}</span></td><td>${esc(e.localidade)}</td><td>${esc(e.regiao||'Não informado')}</td><td class="money">${money(e.empenhado)}</td><td class="money">${money(e.pago)}</td><td class="money">${money(e.rap_pago)}</td><td><a href="${esc(e.url)}" target="_blank" rel="noopener">Fonte</a></td></tr>`).join('');if(rows.length>250)document.getElementById('emendaRows').insertAdjacentHTML('beforeend',`<tr><td colspan="9" class="source">Exibindo as primeiras 250 linhas desta seleção. Use os filtros para reduzir o conjunto.</td></tr>`)};
  document.getElementById('expenseYear').onchange=renderExpense;document.getElementById('expenseGroup').onchange=renderExpense;document.getElementById('emendaYear').onchange=renderEmendas;document.getElementById('emendaMetric').onchange=renderEmendas;document.querySelectorAll('.money-subtabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.money-subtabs button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.money-subpanel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('money-'+b.dataset.money).classList.add('active')});renderExpense();renderEmendas();
 }else{
  document.getElementById('dinheiro').innerHTML=`<h2>Dinheiro público</h2><div class="notice">Base oficial de gastos do mandato indisponível nesta carga.</div>`;
 }
'''
s=s[:start]+block+s[end:]

# Atualiza a resposta da busca natural sobre emendas sem depender da antiga amostra.
a=s.find("else if(/emenda|recurso|dinheiro publico/.test(n))")
if a!=-1:
    b=s.find("else if(/campanha|fornecedor|despesa eleitoral|receita/.test(n))",a)
    if b==-1:
        raise SystemExit('Fim do bloco de emendas na busca não encontrado')
    new=r'''else if(/emenda|recurso|dinheiro publico/.test(n)&&EO){const year=(n.match(/\b(2019|2020|2021|2022|2023|2024|2025|2026)\b/)||[])[1];const rows=E.filter(e=>!year||String(e.ano)===year);const emp=rows.reduce((a,e)=>a+Number(e.empenhado||0),0),pago=rows.reduce((a,e)=>a+Number(e.pago||0),0),rap=rows.reduce((a,e)=>a+Number(e.rap_pago||0),0),qtd=new Set(rows.map(e=>e.codigo_emenda).filter(Boolean)).size;html=`${year?`Em ${year}`:'Nos anos disponíveis'}, a base oficial carregada contém <b>${qtd} emenda(s) distinta(s)</b> e ${rows.length} linha(s) de execução/localidade, com ${money(emp)} empenhados, ${money(pago)} pagos no orçamento e ${money(rap)} pagos em restos a pagar. Veja a aba Dinheiro público para áreas, regiões e registros.`}'''
    s=s[:a]+new+s[b:]

p.write_text(s,encoding='utf-8')
print('v0.13 aplicada ao index.html')
